head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};

scwin.onpageload = async function() {
	window.check_log = '';
	window.check_log1 = false;
	await WebSquare.util.dynamicCreate("wframe1", "wframe", {
		style: "position: relative;width:auto;height:auto;",
		scope: true,
		src: "/sample/common_link/wframe_SKT-407_(WSQ-2566)_sub.xml",
		mode: "sync"
	}, grp_tdInt);
	check_log = scwin.__getObj('wframe1').getObj("ip1").getValue();
	const fun = wframe1.getObj("scwin").form_onLoadCompleted;
	check_log1 = fun.toString().indexOf('sub.xml');
};

scwin.checkVal1 = function() {
	return check_log == 'sub_test';
};

scwin.checkVal2 = function() {
	// 동적 생성 wframe 의 scwin.form_onLoadCompleted 를 얻지 못하면 onpageload 예외로 check_log1=false 그대로 → false 도 FAIL 되게 숫자 확인
	return typeof check_log1 === 'number' && check_log1 != -1;
};

scwin.checkVal3 = function() {
	return scwin.__getObj('wframe1_ip1').getValue() == 'sub_test';
};
